insert into categories (slug, name, short, description) values
  ('custom-chandeliers', 'Custom Chandeliers', 'Chandeliers', 'Statement pieces designed to order — from grand entry fixtures to intimate dining installations, each engineered around your ceiling height, sightlines, and dimming system.'),
  ('pendants', 'Pendants & Suspension', 'Pendants', 'Sculptural single and multi-drop pendants for kitchens, bars, stairwells, and hospitality spaces. Field-adjustable drops and canopy configurations.'),
  ('sconces-wall', 'Sconces & Wall Lights', 'Sconces', 'Architectural wall luminaires — plaster, brass, and glass forms that graze, wash, or frame. ADA-compliant profiles available across the line.'),
  ('vintage-restored', 'Vintage & Restored', 'Vintage', 'One-of-a-kind antique fixtures rescued, rewired to modern code, and relamped with warm-dim LED — provenance documented on every piece. Listings shown are representative of our restoration bench; one-of-one availability rotates and is confirmed at consultation.'),
  ('retrofit-kits', 'LED Retrofit Systems', 'Retrofit', 'Engineered conversion kits that bring incandescent and fluorescent infrastructure to modern LED — flicker-free drivers, warm-dim, and controls included.'),
  ('vela-series', 'Vela Series — Proprietary LED', 'Vela Series', 'Our proprietary architectural LED line, born from an unmet need inside our own projects — every piece proven on our installs before it''s offered for spec. Spec-grade output, designer-grade finish.')
insert into products (slug, sku, name, category, art, palette, price, price_note, blurb, description, specs, options, lead_time_weeks) values
  ('aurora-cascade-36', 'LW-CH-001', 'Aurora Cascade 36', 'custom-chandeliers', 'chandelier', '["#ffb454","#e2622b"]'::jsonb, 8400, 'from — final quote after design review', 'A 36-point cascading chandelier of hand-blown amber globes on staggered brass stems, tuned to your stairwell or double-height entry.', 'The Aurora Cascade is our signature entry statement: thirty-six hand-blown glass globes descend on individually cut brass stems, forming a falling constellation that we model in 3D around your exact ceiling height and sightlines before fabrication. Integrated 2200K–3000K warm-dim LED means the piece dims like candlelight without a single visible bulb. Each install includes structural blocking review, a custom canopy, and commissioning of the dimming curve on site.', '{"Points of light":"36 (scalable 18–72)","Output":"6,800 lm total, warm-dim 2200–3000K","Drop":"custom, 4–22 ft","Finish":"aged brass, blackened steel, or polished nickel","Control":"0–10V, DALI, Lutron, or Casambi wireless","Rating":"dry / damp"}'::jsonb, '[{"name":"Globe glass","values":["Amber","Opal","Smoke","Clear seeded"]},{"name":"Stem finish","values":["Aged brass","Blackened steel","Polished nickel"]},{"name":"Point count","values":["18","36","54","72"]},{"name":"Control protocol","values":["Phase / TRIAC","0–10V","DALI","Casambi wireless"]}]'::jsonb, int4range(8, 12, '[]')),
  ('meridian-ring-grand', 'LW-CH-002', 'Meridian Ring — Grand', 'custom-chandeliers', 'chandelier', '["#ffd9a0","#c9974d"]'::jsonb, 5900, 'from — sized to order', 'Concentric illuminated rings, 24″ to 96″ diameter, with uplight/downlight zones you can dim independently.', 'Meridian is a family of concentric ring chandeliers machined from aluminum and wrapped in brass or bronze skins. Up and down light zones run on separate channels, so a dining room can hold bright task light on the table while the ceiling glows soft. Built to diameter in one-inch increments; we routinely nest two or three rings for larger rooms.', '{"Diameter":"24–96″, 1″ increments","Output":"up to 12,000 lm (dual zone)","CRI":"≥ 95, R9 > 80","Finish":"brass, bronze, powder-coat RAL to order","Control":"dual-channel dimming, any protocol","Rating":"dry / damp"}'::jsonb, '[{"name":"Diameter","values":["24\"","36\"","48\"","72\"","96\""]},{"name":"Ring count","values":["Single","Double nested","Triple nested"]},{"name":"Skin","values":["Brushed brass","Oil-rubbed bronze","RAL powder-coat"]},{"name":"Light zones","values":["Down only","Up + down dual channel"]}]'::jsonb, int4range(6, 10, '[]')),
  ('branchwork-antler-noir', 'LW-CH-003', 'Branchwork Noir', 'custom-chandeliers', 'chandelier', '["#b3a68c","#6fae9b"]'::jsonb, 7200, 'from', 'Organic cast-bronze branch chandelier with frosted bud diffusers — a sculptural centerpiece for lodge, restaurant, or great-room ceilings.', 'Branchwork Noir is cast in sections from sculpted bronze branches, then assembled and balanced for your room. Frosted glass buds carry high-CRI LED at 2400K. Because the piece is modular, we can shape it long and low over a table, or full and radial for a rotunda — a natural fit for lodges, restaurants, and great rooms.', '{"Span":"36–120″ configurable","Output":"4,200–9,600 lm","Color temp":"2400K fixed or warm-dim","Material":"cast bronze, frosted borosilicate","Control":"TRIAC / ELV / 0–10V","Rating":"dry / damp"}'::jsonb, '[{"name":"Span","values":["48\"","72\"","96\"","120\""]},{"name":"Patina","values":["Noir","Verdigris","Natural bronze"]},{"name":"Layout","values":["Radial","Linear (table)","Asymmetric"]}]'::jsonb, int4range(10, 14, '[]')),
  ('candela-tiered-crystal', 'LW-CH-004', 'Candela Tiered Crystal', 'custom-chandeliers', 'chandelier', '["#ffd9a0","#ffb454"]'::jsonb, 11800, 'from — three-tier base configuration', 'A modern crystal tier chandelier with faceted K9 prisms and candle-glow LED tips — classic sparkle, contemporary geometry.', 'Candela reinterprets the tiered crystal chandelier with clean geometry: machined rings carry rows of faceted K9 crystal prisms, and each ''candle'' tip is a warm-dim LED that fades to ember at 1% brightness. Available in three-, five-, and seven-tier builds. All crystal is individually hung and field-replaceable.', '{"Tiers":"3 / 5 / 7","Crystal":"faceted K9, optional Swarovski upgrade","Output":"5,500–16,000 lm","Dim range":"0.5–100%, flicker-free","Control":"any protocol","Rating":"dry"}'::jsonb, '[{"name":"Tiers","values":["Three","Five","Seven"]},{"name":"Crystal","values":["K9 clear","K9 champagne","Swarovski upgrade"]},{"name":"Frame","values":["Polished nickel","Champagne gold","Matte black"]}]'::jsonb, int4range(10, 16, '[]')),
  ('helios-linear-72', 'LW-CH-005', 'Helios Linear 72', 'custom-chandeliers', 'chandelier', '["#e2622b","#ffb454"]'::jsonb, 4600, 'from', 'A 72″ linear suspension of alternating opal cylinders and brass fins — the dining-table workhorse of the custom line.', 'Helios Linear pairs opal glass cylinders with machined brass fins along an aircraft-cable suspension. Even, glare-free light for tables, kitchen islands, and conference rooms. Cut to length in the shop; specify your table and we handle proportions.', '{"Length":"48–120\", cut to order","Output":"up to 8,000 lm","CCT":"2700K / 3000K / warm-dim","Finish":"brass, black, or custom RAL","Control":"TRIAC / 0–10V / DALI","Rating":"dry / damp"}'::jsonb, '[{"name":"Length","values":["48\"","60\"","72\"","96\"","120\""]},{"name":"Fin finish","values":["Brushed brass","Matte black","Custom RAL"]},{"name":"CCT","values":["2700K","3000K","Warm-dim 1800–3000K"]}]'::jsonb, int4range(5, 8, '[]')),
  ('ember-globe-pendant', 'LW-PD-101', 'Ember Globe Pendant', 'pendants', 'pendant', '["#ffb454","#e2622b"]'::jsonb, 640, 'each — multi-drop discounts apply', 'Hand-blown amber globe on a fabric-wrapped cord, glowing like a held ember. The kitchen pendant we design the rest of the room around.', 'The Ember Globe is a single hand-blown sphere in amber, smoke, or opal glass, suspended on color-matched fabric cord. The integral LED module is hidden in the neck, so the glass reads as pure light. Order singly or as staggered clusters of three, five, or seven with a shared canopy.', '{"Diameter":"8\" / 10\" / 12\"","Output":"800 lm per globe","CCT":"2400K fixed or warm-dim","Drop":"field-adjustable to 10 ft","Control":"TRIAC / ELV","Rating":"dry / damp"}'::jsonb, '[{"name":"Glass","values":["Amber","Smoke","Opal"]},{"name":"Diameter","values":["8\"","10\"","12\""]},{"name":"Configuration","values":["Single","Cluster of 3","Cluster of 5","Cluster of 7"]}]'::jsonb, int4range(3, 5, '[]')),
  ('foundry-dome-16', 'LW-PD-102', 'Foundry Dome 16', 'pendants', 'pendant', '["#c9974d","#b3a68c"]'::jsonb, 780, 'each', 'Spun-brass dome pendant with a white reflector interior — warm downlight with an industrial soul for islands and bars.', 'Foundry Dome is spun from a single sheet of brass, with a matte white interior that throws a wide, even pool of task light. The look is factory heritage; the engine is a 95 CRI warm-dim COB. Specify raw brass and it will patina beautifully over years of service.', '{"Diameter":"12\" / 16\" / 20\"","Output":"1,400 lm","CRI":"≥ 95","Finish":"raw brass, lacquered brass, blackened","Control":"TRIAC / 0–10V","Rating":"dry / damp"}'::jsonb, '[{"name":"Diameter","values":["12\"","16\"","20\""]},{"name":"Finish","values":["Raw brass","Lacquered brass","Blackened steel"]},{"name":"Cord","values":["Black fabric","Brass chain","Rigid stem"]}]'::jsonb, int4range(3, 5, '[]')),
  ('stiletto-vertical-drop', 'LW-PD-103', 'Stiletto Vertical Drop', 'pendants', 'pendant', '["#ffd9a0","#6fae9b"]'::jsonb, 920, 'each — stairwell arrays quoted', 'A 48″ blade of edge-lit glass that hangs like a shard of light. Built for stairwells and double-height voids.', 'Stiletto is a vertical edge-lit optic: a slender 48-inch acrylic-glass blade that carries light down its full length with zero visible source. Hung in arrays at varying drops, it turns a stairwell into a field of falling light. Custom lengths to 96 inches.', '{"Length":"36\" / 48\" / 72\" / 96\"","Output":"1,100 lm per blade","CCT":"2700K / 3500K / tunable white","Drop":"custom per blade, to 30 ft","Control":"0–10V / DALI / DMX for tunable","Rating":"dry"}'::jsonb, '[{"name":"Length","values":["36\"","48\"","72\"","96\""]},{"name":"CCT","values":["2700K","3500K","Tunable white"]},{"name":"Array","values":["Single","Array of 5","Array of 9","Custom array"]}]'::jsonb, int4range(4, 7, '[]')),
  ('lantern-oku-paper', 'LW-PD-104', 'Oku Paper Lantern', 'pendants', 'pendant', '["#f4eddd","#ffb454"]'::jsonb, 540, 'each', 'Washi-paper lantern pendant on a blackened steel ring — soft, cloud-like ambient light in three sculptural profiles.', 'Oku wraps hand-pleated washi paper around a steel skeleton, diffusing its LED core into a soft volumetric glow. Three profiles — sphere, gourd, and column — mix well in staggered groups. Paper shades are replaceable and available in natural, ivory, and persimmon.', '{"Profiles":"sphere / gourd / column","Output":"900 lm","CCT":"2700K","Material":"washi paper, blackened steel","Control":"TRIAC","Rating":"dry"}'::jsonb, '[{"name":"Profile","values":["Sphere","Gourd","Column"]},{"name":"Paper","values":["Natural","Ivory","Persimmon"]},{"name":"Size","values":["Small","Medium","Large"]}]'::jsonb, int4range(3, 6, '[]')),
  ('prisma-tri-cluster', 'LW-PD-105', 'Prisma Tri-Cluster', 'pendants', 'pendant', '["#6fae9b","#ffd9a0"]'::jsonb, 1450, 'per cluster of three', 'Three faceted glass prisms on a shared canopy, each splitting its LED point into soft spectral edges.', 'Prisma hangs three hand-cut glass polyhedra from a single machined canopy. Each prism holds a point-source LED whose light fractures along the facets, casting faint spectral edges on nearby surfaces at dusk. Equal parts fixture and kinetic art.', '{"Cluster":"3 prisms, staggered drops","Output":"1,800 lm total","CCT":"3000K","Glass":"hand-cut low-iron crystal","Control":"ELV / 0–10V","Rating":"dry"}'::jsonb, '[{"name":"Prism mix","values":["Clear","Clear + smoke","Clear + champagne"]},{"name":"Canopy","values":["Matte black","Brushed brass"]}]'::jsonb, int4range(5, 8, '[]')),
  ('halo-plaster-eclipse', 'LW-SC-201', 'Eclipse Plaster Sconce', 'sconces-wall', 'sconce', '["#f4eddd","#c9974d"]'::jsonb, 380, 'each — paintable', 'A paintable plaster disc that floats off the wall on a hidden arm, backlit into a perfect eclipse of warm light.', 'Eclipse is cast in fine plaster and ships ready to paint with your wall color, so the fixture disappears by day and blooms into a halo by night. The LED ring behind the disc is fully serviceable. ADA-compliant projection. Order in three diameters and compose walls of staggered eclipses.', '{"Diameter":"9\" / 13\" / 18\"","Projection":"3.6\" (ADA)","Output":"650 lm","CCT":"2700K warm-dim","Finish":"paintable plaster","Rating":"dry / damp"}'::jsonb, '[{"name":"Diameter","values":["9\"","13\"","18\""]},{"name":"Prime","values":["White primer (paintable)","Raw plaster"]}]'::jsonb, int4range(3, 5, '[]')),
  ('gaslight-torch-modern', 'LW-SC-202', 'Modern Gaslight Torch', 'sconces-wall', 'sconce', '["#ffb454","#e2622b"]'::jsonb, 560, 'each — interior & exterior rated', 'The romance of a gas flame, rebuilt as flicker-free warm-dim LED in a solid brass torch body. Exterior rated.', 'Our Modern Gaslight Torch honors the original gas lanterns we restore — solid brass body, beveled glass panes — but carries a 1800K–2700K warm-dim engine with an optional ember-flicker mode calibrated from real flame footage. Wet-rated for entries, facades, and courtyards.', '{"Height":"18\" / 24\"","Output":"700 lm","CCT":"1800–2700K warm-dim + flicker mode","Material":"solid brass, beveled glass","Control":"TRIAC","Rating":"wet (IP65)"}'::jsonb, '[{"name":"Height","values":["18\"","24\""]},{"name":"Finish","values":["Aged brass","Verdigris","Blackened"]},{"name":"Mode","values":["Steady warm-dim","Ember flicker"]}]'::jsonb, int4range(4, 6, '[]')),
  ('ribbon-brass-wave', 'LW-SC-203', 'Ribbon Wave Sconce', 'sconces-wall', 'sconce', '["#c9974d","#ffd9a0"]'::jsonb, 490, 'each', 'A single ribbon of brushed brass folded into a wave, washing the wall above and below with grazing light.', 'Ribbon Wave folds one continuous sheet of brass into a soft S-curve that conceals up- and down-firing LED channels. The grazing light picks up wall texture beautifully — made for plaster, limewash, and brick. Dual channels dim independently.', '{"Width":"5\" — height 14\"","Output":"900 lm (dual channel)","CCT":"2700K","Finish":"brushed brass, blackened, nickel","Control":"dual TRIAC / 0–10V","Rating":"dry / damp"}'::jsonb, '[{"name":"Finish","values":["Brushed brass","Blackened steel","Polished nickel"]},{"name":"Channels","values":["Up + down","Down only"]}]'::jsonb, int4range(3, 5, '[]')),
  ('library-picture-luxe', 'LW-SC-204', 'Gallery Picture Light', 'sconces-wall', 'sconce', '["#ffd9a0","#b3a68c"]'::jsonb, 420, 'each — hardwire or rechargeable', 'Museum-grade picture light with 97 CRI and an anti-glare louver — hardwired or rechargeable for zero-wiring installs.', 'Built for art: 97 CRI, R9 > 90, and a micro-louver that keeps glare off the glass and light on the canvas. The rechargeable version runs 40 hours per charge and mounts with a cleat — no electrician required — making it ideal for gallery walls in older homes.', '{"Width":"12\" / 18\" / 30\"","CRI":"97, R9 > 90","CCT":"2700K / 3000K switchable","Power":"hardwire or rechargeable (40 h)","Finish":"brass, bronze, nickel","Rating":"dry"}'::jsonb, '[{"name":"Width","values":["12\"","18\"","30\""]},{"name":"Power","values":["Hardwired","Rechargeable"]},{"name":"Finish","values":["Brass","Bronze","Nickel"]}]'::jsonb, int4range(2, 4, '[]')),
  ('alcove-step-glow', 'LW-SC-205', 'Alcove Step & Path Glow', 'sconces-wall', 'sconce', '["#6fae9b","#f4eddd"]'::jsonb, 210, 'each — sold in runs', 'Recessed step and corridor light with a shielded, zero-glare aperture. Built to be the quiet workhorse of hospitality corridors.', 'Alcove Glow tucks into stud walls and stair stringers, throwing a low shielded wash across treads and floors. At 1% dim it becomes a night-path system. Specified by the run — we supply engraved circuiting diagrams with every order.', '{"Aperture":"3.5\" trimless or trimmed","Output":"180 lm shielded","CCT":"2400K / 2700K","Voltage":"24V class-2 runs","Control":"0–10V / DALI","Rating":"dry / damp / wet option"}'::jsonb, '[{"name":"Trim","values":["Trimless (mud-in)","Trimmed"]},{"name":"CCT","values":["2400K","2700K"]},{"name":"Rating","values":["Interior","Wet-rated exterior"]}]'::jsonb, int4range(2, 4, '[]')),
  ('1908-beaux-arts-basket', 'LW-VN-301', 'c.1908 Beaux-Arts Crystal Basket', 'vintage-restored', 'vintage', '["#ffd9a0","#c9974d"]'::jsonb, 9800, 'restored one-of-one', 'A Beaux-Arts crystal basket chandelier rescued from a Chicago hotel lobby — fully rewired, relamped warm-dim, provenance documented.', 'Recovered from a 1908 hotel renovation, this crystal basket chandelier arrived with a bent frame and half its strands missing. Our shop straightened and re-silvered the frame, re-strung the crystal with period-correct pinning, rewired to current code, and fitted candelabra LED at 2200K that dims to a true candle ember. Ships with its provenance dossier and a five-year service warranty.', '{"Period":"c. 1908, Beaux-Arts","Size":"32\" dia × 40\" h","Restoration":"frame re-silvered, re-strung, rewired","Lamping":"LED candelabra, 2200K warm-dim","Documentation":"provenance dossier included","Warranty":"5-year service plan"}'::jsonb, '[{"name":"Lamping","values":["Warm-dim LED (recommended)","Period incandescent"]},{"name":"Canopy","values":["Original restored","Reproduction match"]}]'::jsonb, int4range(2, 4, '[]')),
  ('1935-deco-saucer', 'LW-VN-302', 'c.1935 Art Deco Saucer Pendant', 'vintage-restored', 'vintage', '["#6fae9b","#ffd9a0"]'::jsonb, 2900, 'restored one-of-one', 'Stepped opaline glass saucer with nickel banding from a Detroit theater lobby, rewired and relamped for another century.', 'A three-step opaline saucer with original nickel banding, pulled from a shuttered Detroit theater. We stabilized a hairline in the glass with conservation-grade resin (documented), replated the banding, and rebuilt the hanger with modern strain relief. Relamped with a high-CRI LED disc that lights the opaline perfectly evenly.', '{"Period":"c. 1935, Art Deco","Size":"18\" dia × 24\" drop","Restoration":"glass conserved, banding replated","Lamping":"LED disc, 2700K, CRI 95","Documentation":"provenance + conservation notes","Warranty":"5-year service plan"}'::jsonb, '[{"name":"Drop","values":["Original 24\"","Custom drop"]}]'::jsonb, int4range(1, 3, '[]')),
  ('1890-gas-electric-pair', 'LW-VN-303', 'c.1890 Gas-Electric Sconce Pair', 'vintage-restored', 'vintage', '["#ffb454","#c9974d"]'::jsonb, 3400, 'pair — restored one-of-one', 'Transitional gas-electric sconces from the dawn of home electricity, converted to warm-dim LED with ember-flicker gas arms.', 'This pair straddles two eras: the up-turned arms once burned gas while the down-turned arms held early carbon-filament bulbs. Our conversion keeps the story visible — the gas arms now carry calibrated ember-flicker LED, and the electric arms hold 2200K warm-dim candles. Museum-quality brass work throughout.', '{"Period":"c. 1890, transitional gas-electric","Size":"14\" w × 16\" h each","Restoration":"full disassembly, brass restoration","Lamping":"flicker LED (gas arms) + warm-dim (electric)","Documentation":"provenance dossier","Warranty":"5-year service plan"}'::jsonb, '[{"name":"Gas-arm mode","values":["Ember flicker","Steady 1800K"]},{"name":"Finish","values":["Conserved patina","Polished + lacquered"]}]'::jsonb, int4range(2, 4, '[]')),
  ('1962-sputnik-starburst', 'LW-VN-304', 'c.1962 Sputnik Starburst', 'vintage-restored', 'vintage', '["#ffd9a0","#e2622b"]'::jsonb, 2200, 'restored one-of-one', 'An 18-arm atomic-age starburst, rewired with dimmable LED globes that finally do justice to its silhouette.', 'Mid-century Sputniks were always better sculptures than light fixtures — original lamping was harsh and hot. This 18-arm example gets fresh cloth-covered wiring, restored brass arms, and warm 2400K LED globes that dim smoothly to a starfield glow. The atomic silhouette, finally lit right.', '{"Period":"c. 1962","Size":"30\" dia","Restoration":"rewired, arms restored","Lamping":"18× G25 LED, 2400K dim-to-warm","Documentation":"provenance card","Warranty":"5-year service plan"}'::jsonb, '[{"name":"Globe","values":["Opal","Amber","Mixed"]}]'::jsonb, int4range(1, 3, '[]')),
  ('restoration-commission', 'LW-VN-000', 'Your Fixture, Restored — Commission', 'vintage-restored', 'vintage', '["#b3a68c","#ffb454"]'::jsonb, 850, 'assessments from — full quote after inspection', 'Send us the chandelier in your attic. We assess, document, rewire to code, source period parts, and relamp with warm-dim LED.', 'Our restoration commission service takes in family heirlooms, estate finds, and architectural salvage. Every commission begins with a documented assessment — condition, era, parts needed, safety review — followed by a fixed quote. We source period-correct crystal, blow replacement glass, replate finishes, and rewire everything to modern code with discreet LED conversion. White-glove crating both directions.', '{"Intake":"photo assessment, then insured shipping","Scope":"structural, wiring, plating, glass, crystal","Lamping":"warm-dim LED or period lamping","Timeline":"typically 4–12 weeks","Documentation":"full restoration dossier","Warranty":"5-year service plan"}'::jsonb, '[{"name":"Service level","values":["Assessment only","Standard restoration","Museum conservation"]},{"name":"Lamping","values":["Warm-dim LED","Period-correct","Hybrid"]}]'::jsonb, int4range(4, 12, '[]')),
  ('troffer-relight-2x4', 'LW-RF-401', 'TrofferRelight 2×4 Kit', 'retrofit-kits', 'retrofit', '["#6fae9b","#f4eddd"]'::jsonb, 96, 'per fixture — volume pricing on projects', 'Drop-in LED conversion for 2×4 fluorescent troffers: 15 minutes per fixture, ballast eliminated, 62% energy reduction.', 'The workhorse of commercial conversions. TrofferRelight replaces fluorescent tubes and ballast with a magnetic-mount LED panel and flicker-free driver — no fixture replacement, no ceiling work. Typical office sees 62% energy reduction with better light quality and zero ballast maintenance. DLC Premium listed, so it qualifies for utility rebates that we file on your behalf under the turnkey program.', '{"Fits":"standard 2×4 troffers (2×2 kit available)","Output":"4,000–5,000 lm selectable","CCT":"3500K / 4000K / 5000K selectable","Efficacy":"150 lm/W","Control":"0–10V standard; sensor-ready","Listings":"UL, DLC Premium (rebate-eligible)"}'::jsonb, '[{"name":"Size","values":["2×4","2×2","1×4"]},{"name":"Output","values":["4,000 lm","5,000 lm"]},{"name":"Sensor","values":["None","Occupancy + daylight"]}]'::jsonb, int4range(1, 2, '[]')),
  ('highbay-swap-ufo', 'LW-RF-402', 'HighBay Swap UFO 150', 'retrofit-kits', 'retrofit', '["#ffb454","#6fae9b"]'::jsonb, 189, 'per fixture — volume pricing on projects', 'Hook-and-plug replacement for 400W metal-halide high bays. 150W draw, instant-on, motion-dimming standard.', 'Warehouse and gym conversions in one lift-ride per fixture: the UFO 150 hangs from the existing hook and plugs into existing circuits. Replaces 400W metal halide at 150W with better uniformity, instant restrike, and integrated microwave motion dimming that drops to 20% when aisles are empty.', '{"Replaces":"250–400W HID high bays","Output":"22,500 lm","Efficacy":"150 lm/W","CCT":"4000K / 5000K","Control":"integrated motion + daylight","Listings":"UL, DLC Premium (rebate-eligible)"}'::jsonb, '[{"name":"Wattage","values":["100W","150W","200W"]},{"name":"CCT","values":["4000K","5000K"]},{"name":"Optics","values":["90° aisle","120° open"]}]'::jsonb, int4range(1, 2, '[]')),
  ('candelabra-warm-dim', 'LW-RF-403', 'Chandelier Warm-Dim Relamp Set', 'retrofit-kits', 'retrofit', '["#ffd9a0","#ffb454"]'::jsonb, 24, 'per lamp — sets of 12+', 'Candelabra LED lamps that dim from 2700K to 1800K ember — the only retrofit lamp we trust inside restored chandeliers.', 'Most LED candle lamps ruin antique fixtures — wrong color, visible diodes, buzzy dimming. These are the lamps our restoration bench specifies: a spiral filament in hand-tinted glass, 95 CRI, and a true warm-dim curve calibrated against gas flame. Flicker-free on the dimmers we specify, and we test compatibility with yours before shipping.', '{"Base":"E12 candelabra / E26 adapter","Output":"350 lm each","CCT":"2700K → 1800K warm-dim","CRI":"95, R9 85","Life":"25,000 h","Dimmer testing":"included with every order"}'::jsonb, '[{"name":"Shape","values":["Torpedo","Flame tip","Globe G16"]},{"name":"Glass","values":["Clear","Amber tint","Spun frost"]},{"name":"Set","values":["12","24","48"]}]'::jsonb, int4range(1, 2, '[]')),
  ('track-relight-heads', 'LW-RF-404', 'TrackRelight Retail Heads', 'retrofit-kits', 'retrofit', '["#e2622b","#ffd9a0"]'::jsonb, 74, 'per head — volume pricing', 'LED track heads that click into existing halogen track systems — 90 CRI retail punch at a fifth of the wattage.', 'Keep the track, swap the heads. TrackRelight heads fit H, J, and L track standards, replacing 75W halogen PAR30s with 15W high-CRI LED that keeps merchandise color true. Interchangeable optics let a shop re-aim from wall-wash to 15° accent without tools.', '{"Compatibility":"H / J / L track","Output":"1,300 lm","CRI":"90+, R9 60+","CCT":"2700K / 3000K / 3500K","Optics":"15° / 24° / 38° / wall-wash, swappable","Listings":"UL, DLC (rebate-eligible)"}'::jsonb, '[{"name":"Track standard","values":["H","J","L"]},{"name":"CCT","values":["2700K","3000K","3500K"]},{"name":"Optic","values":["15°","24°","38°","Wall-wash"]}]'::jsonb, int4range(1, 2, '[]')),
  ('dim-control-bridge', 'LW-RF-405', 'Legacy Dimmer Bridge', 'retrofit-kits', 'retrofit', '["#6fae9b","#c9974d"]'::jsonb, 145, 'per zone', 'Makes century-old wiring speak modern dimming — a driver-side bridge that adds smooth 0.5% dimming and app control without rewiring walls.', 'The hardest part of retrofitting older buildings is the wiring you can''t touch. The Legacy Dimmer Bridge installs at the fixture or panel side and translates whatever the wall switch does into a clean digital dimming signal — then adds wireless scene control on top. Historic buildings get modern control with zero wall surgery.', '{"Input":"existing switched or dimmed circuits","Output":"0.5–100% flicker-free dimming","Wireless":"Casambi / Bluetooth mesh, app scenes","Capacity":"150W LED per zone","Install":"fixture-side or panel-side","Listings":"UL"}'::jsonb, '[{"name":"Mount","values":["Fixture-side","Panel-side"]},{"name":"Control","values":["App only","App + wall scene keypad"]}]'::jsonb, int4range(1, 3, '[]')),
  ('vela-linea-channel', 'VELA-501', 'Vela Linea Channel', 'vela-series', 'vela', '["#ffd9a0","#6fae9b"]'::jsonb, 68, 'per ft, cut to order', 'Our flagship plaster-in linear channel: a seamless line of dot-free light, born from a detail our own projects demanded.', 'Vela Linea exists because no channel on the market gave us a truly seamless, dot-free line at warm color temperatures with a plaster-in edge we trusted. So we engineered our own with our manufacturing partner. Cut to the millimeter, mitered corners welded light-tight, and driven by remote drivers we mount where they can be serviced. Proven on our own installs before it''s offered for spec.', '{"Profile":"plaster-in, 0.9\" aperture","Output":"300–900 lm/ft","CCT":"2200K–4000K static or warm-dim","CRI":"≥ 95, R9 > 90","Run length":"unlimited with remote drivers","Control":"0–10V / DALI / DMX"}'::jsonb, '[{"name":"Output","values":["300 lm/ft","600 lm/ft","900 lm/ft"]},{"name":"CCT","values":["2200K","2700K","3000K","Warm-dim"]},{"name":"Corner","values":["Straight runs","Mitered corners","Radius curve"]}]'::jsonb, int4range(3, 5, '[]')),
  ('vela-punto-mini', 'VELA-502', 'Vela Punto Mini Downlight', 'vela-series', 'vela', '["#ffb454","#f4eddd"]'::jsonb, 118, 'each — project pricing available', 'A 2″ trimless downlight with the deepest regress in its class — you see light, never the source.', 'Punto was designed for hospitality ceilings, where glare control is everything. A 2-inch aperture with 45° cutoff and a regressed optic means guests see pools of light on tables, never a bright hole in the ceiling. Mud-in trimless or flanged, wet-rated for showers and eaves.', '{"Aperture":"2\" trimless or flanged","Output":"800 lm","Cutoff":"45°, UGR < 10","CCT":"2700K / 3000K / warm-dim","CRI":"≥ 95","Rating":"IC, wet location option"}'::jsonb, '[{"name":"Trim","values":["Trimless mud-in","Flanged"]},{"name":"CCT","values":["2700K","3000K","Warm-dim"]},{"name":"Beam","values":["25°","40°","60°"]}]'::jsonb, int4range(2, 4, '[]')),
  ('vela-arco-uplight', 'VELA-503', 'Vela Arco Cove Uplight', 'vela-series', 'vela', '["#c9974d","#ffd9a0"]'::jsonb, 54, 'per ft', 'Asymmetric cove optic that throws light deep across a ceiling plane from a shallow 1.5″ pocket.', 'Standard cove strips waste half their light inside the pocket. Arco''s asymmetric lens pushes the beam out and across, evenly washing ceilings up to 16 feet deep from a pocket just 1.5 inches tall. The detail that makes a floating ceiling look lit from nowhere.', '{"Pocket":"1.5\" minimum height","Throw":"up to 16 ft even wash","Output":"450 lm/ft","CCT":"2400K–3500K, tunable option","CRI":"≥ 95","Control":"0–10V / DALI"}'::jsonb, '[{"name":"CCT","values":["2400K","2700K","3000K","Tunable"]},{"name":"Length","values":["Cut to order"]}]'::jsonb, int4range(2, 4, '[]')),
  ('vela-firma-exterior', 'VELA-504', 'Vela Firma Façade Grazer', 'vela-series', 'vela', '["#6fae9b","#ffb454"]'::jsonb, 240, 'per 4-ft section', 'Marine-grade façade grazer with interchangeable optics — the exterior workhorse of the Vela line.', 'Firma grazes brick, stone, and board-formed concrete with tight optical control and a marine-grade housing warrantied for ten years outdoors. Snap-change optics (6°×6° to 60°×10°) let designers tune the graze on site. Built for landmark façade work.', '{"Section":"4 ft, linkable","Output":"1,100 lm/ft","Optics":"6×6° / 10×60° / 30×30° / 60×10°","CCT":"2700K / 3000K / RGBW option","Housing":"marine-grade aluminum, IP67","Warranty":"10-year exterior"}'::jsonb, '[{"name":"Optic","values":["6×6°","10×60°","30×30°","60×10°"]},{"name":"CCT","values":["2700K","3000K","RGBW"]}]'::jsonb, int4range(3, 6, '[]')),
  ('vela-scena-controller', 'VELA-505', 'Vela Scena Scene Engine', 'vela-series', 'vela', '["#ffd9a0","#e2622b"]'::jsonb, 640, 'per zone controller', 'The brain of a Vela installation: astronomical scheduling, circadian curves, and one-button scenes for up to 64 zones.', 'Scena runs whole-building lighting scenes without a programmer on retainer. Astronomical clock, circadian warm-dim curves that track sunset, and scene keypads your staff actually understand. Commissioned by our team as part of every turnkey project; available separately for integrators.', '{"Zones":"64 per engine, linkable","Protocols":"DALI-2, 0–10V, DMX, Casambi","Scenes":"astronomical + circadian scheduling","Interface":"keypads, app, BMS integration","Commissioning":"included on turnkey projects","Listings":"UL"}'::jsonb, '[{"name":"Zones","values":["16","32","64"]},{"name":"Keypads","values":["None","2-scene","6-scene engraved"]}]'::jsonb, int4range(2, 4, '[]'))
